<?php $roles = $roles ?? []; $permissions = $permissions ?? []; $matrix = $matrix ?? []; $labels = ['organization_admin' => 'Organization Admin', 'branch_manager' => 'Branch Manager', 'receptionist' => 'Receptionist']; ?>
<div class="roles-heading"><div><div class="breadcrumb"><a href="<?= site_url('dashboard') ?>">Dashboard</a><span class="breadcrumb__sep">/</span><span>Roles &amp; permissions</span></div><span class="eyebrow">Access governance</span><h1>Roles &amp; permissions</h1><p>Define the capabilities available to each tenant-facing role across the platform.</p></div><span class="roles-heading__status"><span></span>Policy controls active</span></div>
<div class="roles-notice"><span class="roles-notice__icon">i</span><div><strong>Super Admin access is always unrestricted</strong><p>This policy applies to organization admins, branch managers, and receptionists. Changes are recorded in the audit log.</p></div></div>
<form method="post" action="<?= site_url('admin/roles-permissions') ?>">
  <?= csrf_field() ?>
  <div class="permission-table-wrap"><table class="permission-table"><thead><tr><th>Capability</th><?php foreach ($roles as $role): ?><th><span><?= esc($labels[$role] ?? $role) ?></span><small><?= $role === 'organization_admin' ? 'Organization-wide' : ($role === 'branch_manager' ? 'Location scope' : 'Front desk') ?></small></th><?php endforeach; ?></tr></thead><tbody><?php foreach ($permissions as $permission => $label): ?><tr><td><strong><?= esc($label) ?></strong><small>Allow this role to access the related workflow.</small></td><?php foreach ($roles as $role): ?><td><label class="permission-toggle"><input type="checkbox" name="<?= esc($role . '_' . $permission) ?>" value="1" <?= !empty($matrix[$role][$permission]) ? 'checked' : '' ?>><span></span><em><?= !empty($matrix[$role][$permission]) ? 'Allowed' : 'Restricted' ?></em></label></td><?php endforeach; ?></tr><?php endforeach; ?></tbody></table></div>
  <div class="roles-actions"><span>Use least-privilege access for tenant teams.</span><button type="submit" class="btn btn-primary">Save permission policy</button></div>
</form>
<div class="roles-footer"><div><span class="eyebrow">Policy guidance</span><h2>Keep responsibilities clear</h2><p>Receptionists usually need visitor workflows only. Give export access to trusted administrators who handle reporting and compliance requests.</p></div><a href="<?= site_url('audit-log') ?>" class="btn btn-secondary btn-sm">Review policy changes</a></div>
